type Field = [string, string, string, string?, boolean?];
const products: CatalogEnrichmentProduct[] = [];
const profiles: Record<string, Partial<WaveFourteenCompanySeed>> = {};
const sources = new Map(provenance.sources.map(s => [s.url, s.sha256]));
