function add(companySlug: string, product: string, pageUrl: string, subclass: string, fields: Field[], zh: string, en: string, locator = 'Product specifications', level: 'model' | 'family' | 'platform' = 'model') {
  const software = ['development-tool', 'robot-model', 'application-software'].includes(subclass);
  const hand = ['dexterous-hand','gripper','robot-arm'].includes(subclass);
  const accessory = subclass === 'power-supply';
  const joint = subclass === 'integrated-joint';
  const controller = subclass === 'embedded-controller';
  const id = `catalog-cnrobotics-${companySlug}-${product.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`;
  const hash = sources.get(pageUrl);
  const p: CatalogEnrichmentProduct = {
    id, companySlug, product, pageUrl, subclass, level,
    category: software || controller ? 'model-software' : hand ? 'end-effector' : accessory || joint ? 'motion' : 'robot-platform',
    primary: software ? 'software-tools' : controller ? 'control-compute' : hand ? 'manipulator-end-effector' : joint ? 'motion-transmission' : accessory ? 'power-energy' : 'robot-platform',
    useCases: ['research', 'integration'], coverage: fields.length ? 'official-partial' : 'capability-only',
    specificationKind: fields.length ? 'parameters' : 'capabilities',
    type: l(software ? '机器人软件与研究平台' : subclass==='robot-arm' ? '机械臂' : subclass==='gripper' ? '夹爪' : hand ? '灵巧手' : joint ? '集成关节' : controller ? '控制器' : accessory ? '机器人配套补能设备' : '机器人平台', software ? 'Robotics software and research platform' : subclass==='robot-arm' ? 'Robot arm' : subclass==='gripper' ? 'Gripper' : hand ? 'Dexterous hand' : joint ? 'Integrated joint' : controller ? 'Controller' : accessory ? 'Robot energy-support equipment' : 'Robot platform'),
    overview: [l(zh, en)],
    applications: [l(software ? '算法开发、数据处理与机器人部署验证。' : hand ? '接触操作、交互与末端集成。' : '按厂商列出的研究、服务或作业场景进行集成评估。', software ? 'Algorithm development, data processing and robot deployment validation.' : hand ? 'Contact manipulation, interaction and end-effector integration.' : 'Integration evaluation for the research, service or operational scenarios identified by the manufacturer.')],
    integration: l('按本型号的机械、电气、软件版本及供货清单确认接口；附件不自动继承本体能力。', 'Confirm mechanical, electrical and software revisions against the exact model and packing list; accessories do not inherit host capabilities.'),
    verification: l('仅转录明确列出的规格。条件性实验值、来源冲突和未公开数据不进入数值筛选；本条不表示公司全目录已完成。', 'Only explicitly published specifications are transcribed. Conditional experiments, conflicting values and undisclosed data are excluded from numeric filtering; this entry does not establish full company-catalog completion.'),
    rows: fields.map(([labelZh,labelEn,valueZh,valueEn,exclude],index) => ({
      label:l(labelZh,labelEn),value:l(valueZh,valueEn??valueZh),sourceUrl:pageUrl,
      sourceLabel:l(`${product} 官方资料`,`${product} official material`),
      locator:l(`${product}; ${locator}; ${labelZh}; 转录行 ${index+1}${hash?`; cached SHA256 ${hash}`:''}`,`${product}; ${locator}; ${labelEn}; transcription row ${index+1}${hash?`; cached SHA256 ${hash}`:''}`),
      excludeFromNumericIndex:exclude??software,
      ...(exclude ? {conditions:l('保留来源的工况、上限或歧义；不作为无条件额定能力。','Retains the source condition, limit or ambiguity; not an unconditional rated capability.')} : {}),
    })),
    sourceLinks:[{label:l('官方型号资料','Official model material'),url:pageUrl}],
  };
  products.push(p);return p;
}

