// Closeout is append-only; the importer freezes the original 58 delivered products.
function evidence(p: CatalogEnrichmentProduct, url: string, locator: string, fields: Field[]) {
  const start=p.rows.length;
  p.rows.push(...fields.map(([zh,en,value,valueEn,exclude],i)=>({label:l(zh,en),value:l(value,valueEn??value),sourceUrl:url,sourceLabel:l('官方型号规格','Official model specification'),locator:l(`${p.product}; ${locator}; ${zh}; row ${start+i+1}`,`${p.product}; ${locator}; ${en}; row ${start+i+1}`),excludeFromNumericIndex:exclude??false,...(exclude?{conditions:l('保留本行来源条件、峰值或冲突，不作无条件额定值。','Retains the row-specific condition, peak or conflict; not an unconditional rating.')}: {})})));
  p.sourceLinks??=[];
  if(!p.sourceLinks.some(s=>s.url===url))p.sourceLinks.push({label:l('官方规格原件','Original official specification'),url});
  p.coverage='official-partial';p.specificationKind='parameters';return p;
}
