for(const [slug,aboutUrl,,,scopeZh,scopeEn] of companyNotes) profiles[slug]={
 aboutUrl,overview:businessOverviews[slug],catalogScope:l(scopeZh,scopeEn),
 verificationFocus:l('以逐型号参数与公开证据为边界；尚存条目级缺口，不宣称全公司目录完成。','Model-level specifications and public evidence define the scope; itemized gaps remain, so full company-catalog completion is not claimed.'),
 investmentView:[l('融资金额、估值、订单、产能与营业收入不是同一口径。未获得财报的条目不推断收入、利润或现金流。','Funding, valuation, orders, capacity and revenue are different measures. Entries without financial statements do not infer revenue, profit or cash flow.')],
};
function event(slug:string,date:string,kind:'founding'|'product'|'funding'|'business',zh:string,en:string,sourceUrl:string){
 (profiles[slug].timeline??=[]).push({date,kind,title:l(zh,en),detail:l(zh,en),sourceUrl});
}
function funding(slug:string,date:string,roundZh:string,roundEn:string,amountZh:string,amountEn:string,investorsZh:string,investorsEn:string,url:string){
 (profiles[slug].funding??=[]).push({date,round:l(roundZh,roundEn),amount:l(amountZh,amountEn),investors:l(investorsZh,investorsEn),sourceUrl:url});
 event(slug,date,'funding',`${roundZh}：${amountZh}（公司公告口径）。`,`${roundEn}: ${amountEn} (company disclosure).`,url);
}
