// Parent-authorized source correction; historical data and original row values stay immutable.
export function applyCnRoboticsNumericConflictExclusions(items: CatalogEnrichmentProduct[]) {
 const g2Source = 'https://www.agibot.com/filepage/296.html';
 const g2Conflict = l(
  '头部屏幕尺寸来源冲突：同一G2手册2.3规格表为6.3英寸，6.3表情章节为6.36英寸。两种原值均保留并排除数值索引；不推定舍入关系或新硬件版本。',
  'Head-screen size source conflict: G2 manual section 2.3 specifies 6.3 inches, while section 6.3 Expressions states 6.36 inches. Both original values are retained and excluded from numeric indexing; neither rounding nor a new hardware revision is inferred.');
 const ultraWConflict = l(
  '整机自由度来源冲突：Ultra-W技术规格表第1页为16，型号手册物理第11页（印刷第09页）正文为12。两种原值均保留并排除数值索引；不推定是否包含车轮自由度或新版本。单腿4自由度是不同指标，不在本次纠错范围。',
  'Whole-body DoF source conflict: the Ultra-W technical sheet p1 states 16, while the model manual physical p11 (printed p09) states 12. Both original values are retained and excluded from numeric indexing; wheel inclusion and a new revision are not inferred. Four DoF per leg is a different metric outside this correction.');
 const rules = [
  {product:'AGIBOT G2', label:'Head interactive screen size', source:g2Source, conflict:g2Conflict},
  {product:'AGIBOT G2', label:'Screen-size section discrepancy', source:g2Source, conflict:g2Conflict},
  {product:'AGIBOT D1 Ultra-W', label:'Total DoF', source:'https://www.agibot.com/file/ueditor/php/upload/file/20260911/1789114917251810.pdf', conflict:ultraWConflict},
  {product:'AGIBOT D1 Ultra-W', label:'Manual DoF source conflict', source:'https://www.agibot.com/file/ueditor/php/upload/file/20260911/1789114813366034.pdf', conflict:ultraWConflict},
 ];
 for (const product of items) {
  if (product.companySlug !== 'agibot') continue;
  for (const row of product.rows) {
   const rule = rules.find(item => item.product === product.product && item.label === row.label.en && item.source === row.sourceUrl);
   if (!rule) continue;
   row.excludeFromNumericIndex = true;
   row.conditions = l(...(['zh','en'] as const).map(locale => {
    const previous = row.conditions?.[locale] ?? '';
    return previous.includes(rule.conflict[locale]) ? previous : [previous,rule.conflict[locale]].filter(Boolean).join(' ');
   }) as [string,string]);
  }
 }
}
applyCnRoboticsNumericConflictExclusions(products);

// Separately authorized block4 corrections are scoped to exact model/metric/source triples.
export function applyCnRoboticsBlock4ConflictExclusions(items: CatalogEnrichmentProduct[]) {
 const maxManual = 'https://www.agibot.com/file/ueditor/php/upload/file/20260825/1787637877608670.pdf';
 const proManual = 'https://www.agibot.com/file/ueditor/php/upload/file/20260924/1790221504950299.pdf';
 const payload = l(
  '同型号负载来源冲突：D1 Max网页Rated payload为25 kg，型号手册物理第11页（印刷09页）Effective Payload为30 kg。两种原文和来源保留，相关行排除数值索引；额定/有效口径及版本未解决，不推定新配置。',
  'Same-model payload source conflict: D1 Max webpage Rated payload is 25 kg; model-manual physical p11 (printed p09) Effective Payload is 30 kg. Original wording and sources are retained; both rows are excluded from numeric indexing. Rated/effective scope and revision remain unresolved; no new configuration is inferred.');
 const energy = l(
  '同型号电池能量来源冲突：D1 MaxPro网页及手册物理第7页为2081 Wh，手册物理第5页概述为2123 Wh。两种原值保留并排除数值索引，不推定新电池版本；不修改Ah容量、电压或充电器输出指标。',
  'Same-model battery-energy source conflict: D1 MaxPro webpage and manual physical p7 state 2081 Wh; manual physical p5 overview states 2123 Wh. Both original values are retained and excluded from numeric indexing, without inferring a new battery revision. Ah capacity, voltage and charger-output metrics are unchanged.');
 const wading = l(
  '同型号涉水深度来源冲突：D1 MaxPro网页为20 cm，型号手册物理第5页概述为30 cm。两种原值保留并排除数值索引；版本与测试工况未解决，不据此替换IP防护等级或台阶高度。',
  'Same-model wading-depth source conflict: D1 MaxPro webpage states 20 cm; model-manual physical p5 overview states 30 cm. Both original values are retained and excluded from numeric indexing. Revision and test conditions remain unresolved; IP rating and stair height are different metrics and unchanged.');
 const speed = l(
  '同型号空载速度来源差异：MaxPro手册物理第5页概述为2.5 m/s；技术表及手册物理第7至8页分别保留实验室3 m/s、实际软件限2 m/s工况。相关来源行排除数值索引，不将这些工况合并为额定速度。原文高速版3.5 m/s未给独立型号，不能当作标准版实测值；持续步行0至1.2 m/s为不同指标，不改动。',
  'Same-model no-load speed source discrepancy: the MaxPro manual physical p5 overview states 2.5 m/s; the technical sheet and manual physical pp7-8 retain separate laboratory 3 m/s and actual software-limited 2 m/s conditions. Both source rows are excluded from numeric indexing, not combined into a rated speed. The original high-speed-version 3.5 m/s has no distinct model code and is not treated as a standard-version measurement. Continuous walking 0 to 1.2 m/s is a different metric and unchanged.');
 const rules = [
  {product:'AGIBOT D1 Max',label:'Rated payload',source:'https://www.agibot.com/products/D1_Max',condition:payload},
  {product:'AGIBOT D1 Max',label:'Manual effective payload discrepancy',source:maxManual,condition:payload},
  {product:'AGIBOT D1 MaxPro',label:'Battery energy',source:'https://www.agibot.com/products/D1_MaxPro',condition:energy},
  {product:'AGIBOT D1 MaxPro',label:'Manual overview battery-energy discrepancy',source:proManual,condition:energy},
  {product:'AGIBOT D1 MaxPro',label:'Wading depth',source:'https://www.agibot.com/products/D1_MaxPro',condition:wading},
  {product:'AGIBOT D1 MaxPro',label:'Manual overview wading-depth discrepancy',source:proManual,condition:wading},
  {product:'AGIBOT D1 MaxPro',label:'No-load test speed and software limit',source:'https://www.agibot.com/file/ueditor/php/upload/file/20260924/1790218091376633.pdf',condition:speed},
  {product:'AGIBOT D1 MaxPro',label:'Manual overview speed discrepancy',source:proManual,condition:speed},
 ];
 for (const product of items) {
  if (product.companySlug !== 'agibot') continue;
  for (const row of product.rows) {
   const rule = rules.find(r => r.product === product.product && r.label === row.label.en && r.source === row.sourceUrl);
   if (!rule) continue;
   row.excludeFromNumericIndex = true;
   row.conditions = l(...(['zh','en'] as const).map(locale => {
    const previous = row.conditions?.[locale] ?? '';
    return previous.includes(rule.condition[locale]) ? previous : [previous,rule.condition[locale]].filter(Boolean).join(' ');
   }) as [string,string]);
  }
 }
}
applyCnRoboticsBlock4ConflictExclusions(products);

export function applyCnRoboticsBlock10Profiles(items: Record<string, Partial<WaveFourteenCompanySeed>>) {
 const targets = continuationBlock10.profiles.map(addition => {
  const profile = items[addition.slug];
  if (!profile) throw new Error(`Missing existing cnRobotics profile: ${addition.slug}`);
  return {addition,profile};
 });
 for (const {addition,profile} of targets) {
  for (const paragraph of addition.overview) {
   if (!profile.overview?.some(old => old.zh === paragraph.zh && old.en === paragraph.en)) (profile.overview ??= []).push(structuredClone(paragraph));
  }
  for (const item of addition.timeline) {
   if (!profile.timeline?.some(old => old.date === item.date && old.sourceUrl === item.sourceUrl && old.title.en === item.title.en)) (profile.timeline ??= []).push({...structuredClone(item),kind:item.kind as 'product'|'business'});
  }
 }
}
applyCnRoboticsBlock10Profiles(profiles);

